function attr(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
}

// 会话缺失或 Origin 不合时的 403 页面：只回显稳定错误码与服务端提示，绝不回显 token。
export function renderDenied(options) {
  const opts = options || {};
  const code = attr(opts.code || 'forbidden');
  const hint = attr(opts.hint || '请使用看板启动时在终端打印的一次性登录链接。');
  return `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>需要登录 · Agent Bus</title>
  <style>
    html{background:#0d1117;color:#c9d1d9;font:15px/1.7 "Segoe UI","Microsoft YaHei",sans-serif}
    body{margin:0;min-height:100vh;display:grid;place-items:center;padding:32px}
    .card{max-width:560px;border:1px solid #2a3646;border-radius:16px;padding:30px 32px;background:#131b26;box-shadow:0 20px 60px rgba(0,0,0,.4)}
    h1{font-size:19px;margin:0 0 14px;color:#e6edf3}
    p{margin:0 0 12px;color:#9aa7b6}
    code{background:#1d2836;border-radius:6px;padding:2px 7px;font-family:Consolas,monospace;font-size:13px;color:#9ecbff}
  </style>
</head>
<body><div class="card">
  <h1>看板会话无效</h1>
  <p>这个控制台只接受带会话 cookie 的本机访问。请用启动时终端打印的一次性登录链接打开看板。</p>
  <p>错误码：<code>${code}</code></p>
  <p>${hint}</p>
</div></body>
</html>`;
}

